import{_ as l,o as r,c as t,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph Developer Monthly 2023-04-05","description":"","frontmatter":{"title":"Ceph Developer Monthly 2023-04-05","date":"2023-04-05T00:00:00.000Z","updated":"2023-04-08T00:00:00.000Z","tags":["Ceph","Distributed Storage","OpenEuler","CI/CD","Performance Counters"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_Developer_Monthly_2023-04-05.md","filePath":"posts/2023/Ceph_Developer_Monthly_2023-04-05.md","lastUpdated":1780460162000}'),i={name:"posts/2023/Ceph_Developer_Monthly_2023-04-05.md"};function a(n,e,p,s,u,h){return r(),t("div",null,[...e[0]||(e[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题：</strong> 开发者月度会议 - 友好版<br><strong>日期：</strong> 2023年4月5日<br><strong>主持人：</strong> Radic<br><strong>出席人员：</strong> Kevin, Laura, 以及其他开发者和社区成员</p><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>引入 openEuler 至 Upstream</strong></p><ul><li>Kevin 分享了将 openEuler 操作系统引入 Ceph Upstream 的想法。</li><li>openEuler 是一个中国最大的开源操作系统社区，拥有丰富的用户和商业发行版。</li><li>openEuler 的 SDS SIG 致力于开发和维护存储相关功能，并已提交相关页面至 Upstream。</li><li>讨论了如何确保 openEuler 的 LGS 支持在 Upstream 中运行，并探讨了如何将 openEuler 的构建集成到 Upstream 的 CI 系统中。</li></ul></li><li><p><strong>技术讨论</strong></p><ul><li>讨论了在 Upstream 中支持新操作系统的技术细节，包括构建规范、自动化测试、资源需求等。</li><li>提到了 openEuler 的存储 SIG 已经有一些自动构建，但需要更多硬件资源来执行构建。</li></ul></li><li><p><strong>PR 讨论</strong></p><ul><li>讨论了提交到 Upstream 的 PR，特别是关于 openEuler 的 spec 文件更改。</li><li>确认了 spec 文件在 main 分支上已知可以工作，建议先贡献到 main 分支，然后再回溯到特定分支。</li></ul></li><li><p><strong>反馈和后续行动</strong></p><ul><li>讨论了从 Upstream 和 openEuler 社区获得的反馈，以及如何继续贡献支持。</li><li>确认了 openEuler 社区可以提供硬件资源来帮助 Upstream 设置自动化作业。</li><li>讨论了如何确保 Centos 和 RHEL 的包仍然可以构建。</li></ul></li><li><p><strong>其他议题</strong></p><ul><li>讨论了在 Reef 版本中切换某些组件从使用旧的未标记计数器到新的标记计数器的问题。</li><li>讨论了 perf 计数器是否应被视为公共 API 的一部分，以及如何在社区中形成共识。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>确认了 openEuler 的 spec 文件在 main 分支上已知可以工作，建议先贡献到 main 分支，然后再回溯到特定分支。</li><li>确认了 openEuler 社区可以提供硬件资源来帮助 Upstream 设置自动化作业。</li><li>讨论了如何在社区中形成关于 perf 计数器是否应被视为公共 API 的共识。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>继续贡献支持 openEuler 在 Upstream 中的运行。</li><li>提供硬件资源帮助 Upstream 设置自动化作业。</li><li>在社区中讨论并形成关于 perf 计数器是否应被视为公共 API 的共识。</li><li>在 7.io 网站上提及 openEuler 的存储 SIG 仓库。</li></ul><p><strong>会议结束：</strong> 感谢所有参与者的讨论，期待下个月的会议。</p>',9)])])}const m=l(i,[["render",a]]);export{d as __pageData,m as default};
